<div class="page-heading"><p class="eyebrow">Administration</p><h1>Taxonomy Management</h1><p>Maintain the controlled lists used to classify documentation.</p></div><?php require base_path('views/admin/_nav.php'); ?><div class="admin-columns"><section class="panel"><ul class="nav nav-tabs" role="tablist"><?php foreach(array_keys($taxonomies) as $table):?><li class="nav-item"><button class="nav-link <?=$activeTab===$table?'active':''?>" data-bs-toggle="tab" data-bs-target="#<?=$table?>" type="button"><?=e(ucfirst($table))?></button></li><?php endforeach;?></ul><div class="tab-content pt-3"><?php foreach($taxonomies as $table=>$items):?><div class="tab-pane fade <?=$activeTab===$table?'show active':''?>" id="<?=$table?>"><div class="taxonomy-list"><?php foreach($items as $item):?><div><span><strong><?=e($item['name'])?></strong><small><?=e($item['code']??'')?></small></span><span class="badge <?=$item['is_active']?'text-bg-success':'text-bg-secondary'?>"><?=$item['is_active']?'Active':'Archived'?></span><?php if($item['is_active']):?><form method="post" action="/admin/taxonomies/<?=$table?>/archive"><?=csrf_field()?><input type="hidden" name="id" value="<?=$item['id']?>"><button class="btn btn-sm btn-outline-danger" title="Archive" data-confirm="Archive this entry? Existing article links will remain."><i class="bi bi-archive"></i></button></form><?php endif;?></div><?php endforeach;?></div></div><?php endforeach;?></div></section><aside class="panel"><h2>Create entry</h2><form method="post" data-loading-form><?=csrf_field()?><label class="form-label">Taxonomy</label><select class="form-select mb-3" name="taxonomy" required><?php foreach(array_keys($taxonomies) as $table):?><option value="<?=$table?>"><?=e(ucfirst($table))?></option><?php endforeach;?></select><label class="form-label">Name</label><input class="form-control mb-3" name="name" required maxlength="120"><label class="form-label">Code</label><input class="form-control mb-3" name="code" maxlength="50"><button class="btn btn-primary w-100" data-loading-text="Creating..."><span>Create entry</span></button></form></aside></div>
